Section FPX. Context {fx : PropExec.FPState}.

(* [comment removed for export] *)
Lemma sec_h1_fn : forall regs (M rom : word -> option byte) (s sec stat msz n r F : Z),
  getr regs 1 = Z_to_bv 64 0x9644c -> getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 10 = Z_to_bv 64 r -> getr regs 19 = Z_to_bv 64 n ->
  getr regs 21 = Z_to_bv 64 8 -> getr regs 24 = Z_to_bv 64 7 ->
  0x6c4000 <= s - 464 -> s < 2 ^ 47 -> 0 <= n -> n mod 8 = 0 -> 2 ^ 12 <= msz -> n + 4096 <= msz -> 4096 <= r -> r mod 4096 = 0 -> r + msz < 2 ^ 47 ->
  0x10000 <= sec -> sec + 1024 < 0x6c4000 -> 0x10000 <= stat -> stat + 64 < 0x6c4000 -> 0x10000 <= F -> F + 512 < 0x6c4000 ->
  wrA M (s - 464) 464 ->
  cellA M (s - 104) 8 0x5fbe4 -> cellA M (s - 112) 8 stat -> cellA M (s - 120) 8 sec -> cellA M (s - 128) 8 msz ->
  cellA M sec 8 4096 -> cellA M 0x164508 8 F -> cellA M (F + 144) 8 0 ->
  msteps ASEGS (mkst regs (0x94b00 : word) M rom)
    (mkst (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd regs
             1 (Z_to_bv 64 0x5fc3c)) 2 (Z_to_bv 64 (s - 96))) 8 (Z_to_bv 64 stat)) 9 (Z_to_bv 64 sec)) 10 (Z_to_bv 64 r)) 11 (Z_to_bv 64 4096)) 12 (Z_to_bv 64 250))
