Lemma sec_b2_fn : forall regs (M rom : word -> option byte) (s sec stat msz lg nch nres r q F : Z),
  getr regs 1 = Z_to_bv 64 0x968bc -> getr regs 2 = Z_to_bv 64 (s - 192) -> getr regs 8 = Z_to_bv 64 131072 -> getr regs 10 = Z_to_bv 64 q ->
  0x6c4000 <= s - 464 -> s < 2 ^ 47 -> 4096 <= r -> r < 2 ^ 47 -> 0 <= msz < 2 ^ 47 -> 0 <= q < 2 ^ 64 - 4095 ->
  0x10000 <= sec -> sec + 1024 < 0x6c4000 -> 0x10000 <= stat -> stat + 64 < 0x6c4000 -> 0 <= nch < 2 ^ 20 -> 0 <= nres < 2 ^ 40 -> 0 <= lg <= 63 -> 0x10000 <= F -> F + 512 < 0x6c4000 ->
  wrA M (s - 464) 464 -> wrA M sec 624 ->
