  getr regs 21 = Z_to_bv 64 r -> ret_ok x1 ->
  0x6c4000 <= s - 464 -> s < 2 ^ 47 -> 2 ^ 12 <= msz < 2 ^ 47 -> 4096 <= r -> r + msz < 2 ^ 47 -> 0x6c4000 <= r -> 0 <= q < 2 ^ 64 - 4095 ->
  0x10000 <= sec -> sec + 1024 < 0x6c4000 -> sec + 624 <= stat -> stat + 64 < 0x6c4000 -> stat mod 8 = 0 -> 0x10000 <= F -> F + 512 < 0x6c4000 ->
  0 <= nch < 2 ^ 20 -> 0 <= nres < 2 ^ 40 -> 0x6c4000 <= pab -> pab + 8 * nch + 8 < 2 ^ 47 ->
  apart (pab + 8 * nch) 8 r 32 -> apart (pab + 8 * nch) 8 (s - 464) 464 -> apart r 32 (s - 464) 464 ->
  0 <= na -> na < 2 ^ 64 -> 0 <= cur -> cur < 2 ^ 64 -> 0 <= mx < 2 ^ 64 -> 0 <= bsl -> bsl < 2 ^ 64 ->
  0 <= st16 -> st16 < 2 ^ 64 -> 0 <= st24 -> st24 < 2 ^ 64 ->
  wrA M2 (s - 464) 464 -> wrA M2 sec 624 -> wrA M2 (stat + 16) 16 -> wrA M2 (r + 24) 8 -> wrA M2 (pab + 8 * nch) 8 ->
  cellA M2 (s - 104) 8 0x5ff84 -> cellA M2 (s - 112) 8 stat -> cellA M2 (s - 120) 8 sec -> cellA M2 (s - 128) 8 msz -> cellA M2 (s - 136) 8 (63 - Z.log2 msz) -> cellA M2 (s - 144) 8 (4096 + r) ->
  cellA M2 0x164508 8 F -> cellA M2 (F + 144) 8 0 -> cellA M2 (sec + 48) 8 nres -> cellA M2 (sec + 56) 8 nch ->
  cellA M2 (sec + 8) 8 pab -> cellA M2 (sec + 72) 8 na -> cellA M2 (sec + 88) 8 cur -> cellA M2 (sec + 96) 8 mx -> cellA M2 (sec + 104 + 8 * Z.log2 msz) 8 bsl ->
  cellA M2 (stat + 16) 8 st16 -> cellA M2 (stat + 24) 8 st24 ->
